import { describe, expect, test } from 'vitest'
import * as config from './config'
import { PASSIVE_ITEMS, SPELLS } from './spells/data'
import { ORIGINAL } from './spells/reference'

/**
 * Every gameplay number in sim/spells/data.ts and the shop / mastery / pawn / arena constants
 * must equal the original mod's value (spells/reference.ts, generated by the data audit from
 * the original KV and Lua tables). This is the proof that no value is guessed.
 *
 * An intentional deviation must be listed here with its reason and PLAN / research reference.
 * Behavior-level fixes (Drain using its 24.5 radius for collision, Range mastery applied once,
 * Homing rebuilt, ...) do not change any number, so the list is empty.
 */
const DEVIATIONS: Record<string, string> = {
  'DEFAULT_SETTINGS.shopSeconds': 'PLAN §2 (2026-10-16): default shop 25 s instead of 30; still a lobby option',
}

type Num = number | boolean | readonly number[]

function same(ours: unknown, orig: unknown): boolean {
  if (Array.isArray(ours) || Array.isArray(orig)) {
    return Array.isArray(ours) && Array.isArray(orig) && ours.length === orig.length && ours.every((v, i) => same(v, orig[i]))
  }
  if (typeof ours === 'boolean' || typeof orig === 'boolean') return ours === orig
  if (typeof ours !== 'number' || typeof orig !== 'number') return false
  // Lua computes some constants (200 * 1.46, 1300 * (1 - 0.96) / 0.03): compare to 1e-9 relative
  return Math.abs(ours - orig) <= 1e-9 * Math.max(1, Math.abs(orig))
}

function check(key: string, ours: unknown, orig: Num | undefined): void {
  if (key in DEVIATIONS) return
  expect(orig, `${key}: no original reference value (unaudited number)`).not.toBeUndefined()
  expect(same(ours, orig), `${key}: ours ${JSON.stringify(ours)} vs original ${JSON.stringify(orig)}`).toBe(true)
}

type SpellRef = {
  levels: Record<string, readonly number[]>
  consts: Record<string, number>
  cost?: number
  upgradeCosts?: readonly number[]
  column?: number
  cooldown: readonly number[]
  tooltipCooldown?: readonly number[]
  castPoint: number
  maxLevel: number
  immediate?: boolean
  ignoreTurn?: boolean
  targetNone?: boolean
}

describe('spell and item numbers match the original mod (reference.ts)', () => {
  const refs = ORIGINAL.spells as unknown as Record<string, SpellRef>

  test('the reference covers exactly our spell set', () => {
    expect(Object.keys(refs).sort()).toEqual(Object.keys(SPELLS).sort())
  })

  for (const [id, def] of Object.entries(SPELLS)) {
    test(id, () => {
      const r = refs[id]
      expect(r).toBeDefined()
      check(`${id}.cost`, def.cost, r.cost)
      check(`${id}.cooldown`, def.cooldown, r.cooldown)
      check(`${id}.castPoint`, def.castPoint, r.castPoint)
      check(`${id}.maxLevel`, def.maxLevel, r.maxLevel)
      if (def.kind === 'spell') {
        check(`${id}.upgradeCosts`, def.upgradeCosts, r.upgradeCosts)
        check(`${id}.column`, def.column, r.column)
        check(`${id}.immediate`, def.immediate, r.immediate)
        check(`${id}.ignoreTurn`, def.ignoreTurn, r.ignoreTurn)
        check(`${id}.target`, def.target === 'none', r.targetNone)
      }
      if (def.tooltipCooldown) check(`${id}.tooltipCooldown`, def.tooltipCooldown, r.tooltipCooldown)
      for (const [k, v] of Object.entries(def.levels)) check(`${id}.levels.${k}`, v, r.levels[k])
      for (const [k, v] of Object.entries(def.consts)) check(`${id}.consts.${k}`, v, r.consts[k])
      // no stale reference entries either
      expect(Object.keys(r.levels).sort()).toEqual(Object.keys(def.levels).sort())
      expect(Object.keys(r.consts).sort()).toEqual(Object.keys(def.consts).sort())
    })
  }
})

describe('passive items, masteries and core constants match the original', () => {
  test('passive items: cost, max level, per-level stats (server values)', () => {
    const refs = ORIGINAL.passive as unknown as Record<string, { cost: number; maxLevel: number; levels: Record<string, readonly number[]> }>
    expect(Object.keys(refs).sort()).toEqual(Object.keys(PASSIVE_ITEMS).sort())
    for (const [id, def] of Object.entries(PASSIVE_ITEMS)) {
      const r = refs[id]
      check(`${id}.cost`, def.cost, r.cost)
      check(`${id}.maxLevel`, def.maxLevel, r.maxLevel)
      for (const [k, v] of Object.entries(def.levels)) check(`${id}.levels.${k}`, v, r.levels[k])
    }
  })

  test('mastery gains per level', () => {
    for (const k of ['duration', 'range', 'lifesteal'] as const) check(`mastery.${k}`, config.MASTERY_GAIN[k], ORIGINAL.mastery[k])
  })

  test('shop limits, pawn, arena, lava, pillar and mode constants', () => {
    const ours = config as unknown as Record<string, unknown>
    for (const [k, v] of Object.entries(ORIGINAL.config)) {
      if (k === 'DEFAULT_SETTINGS') continue
      check(`config.${k}`, ours[k], v as number)
    }
    for (const [k, v] of Object.entries(ORIGINAL.config.DEFAULT_SETTINGS)) {
      check(`DEFAULT_SETTINGS.${k}`, (config.DEFAULT_SETTINGS as unknown as Record<string, unknown>)[k], v)
    }
  })
})
